INSERT INTO news (kind, title, body) VALUES
 ('update', 'Mapas até o nível 1000 e chão novo nos mapas', 'Abriram Lost Tower 2 a 7 (850 a 975) e Exile (1000), com bosses Senhor da Torre e Rei do Exílio. Lorencia, Noria, Devias, Dungeons, Lost Tower, Atlans, Tarkan, Icarus e as arenas ganharam chão novo, e todo mapa de caça tem uma área segura na entrada onde os monstros não atacam.');
